text_flat:
{
"相机参数": {
"设备类型": "iPhone 15 Pro 前置自拍",
"镜头": "24mm",
"构图": "高角度 POV（第一人称视角）",
"后期处理": "计算摄影风格，清晰的数字读出，深景深"
},
"主体描述": {
"特征": "陶瓷娃娃审美，无瑕的苍白皮肤，巨大的冰蓝色眼睛，小巧的鼻子，翘起的自然色嘴唇",
"表情": "面无表情，空洞，瞪大眼睛注视",
"造型": "白金色的双紧辫发型，鲜艳的蓝色美甲",
"服装": "浅蓝色紧身弹力棉上衣，极深超宽 V 领，深邃锁骨与领口线",
"动作": "抬头仰视镜头，用一只手遮挡刺眼的阳光"
},
"环境与灯光": {
"场景": "广阔的沙滩，背景中模糊的海平线",
"灯光": "高调明亮的沿海日光，5500K 色温，强烈的白沙反光填充，均匀照明",
"质感": "微带露水的无孔皮肤，细腻的反光白沙颗粒"
},
"技术约束": {
"色彩科学": "柔和的粉彩色调，线性中性色，高曝光",
"负面提示词": [
"重阴影",
"雪",
"冬装",
"红指甲",
"黑色上衣",
"保守的领口",
"胶片颗粒感"
]
}
}

{
"type": "品牌形象与周边设计项目",
"theme": {
"color_palette": "{argument name="theme color" default="柔粉色"} 与白色",
"motif": "{argument name="motif" default="樱花"} 与粉色爱心"
},
"character": {
"description": "留着棕色短波波头的动漫少女，粉色眼睛，身穿白色连帽衫，面带温柔微笑"
},
"branding": {
"main_logo": "{argument name="character name" default="癒音ちー"}",
"sub_logo": "{argument name="character subtext" default="ゆおんちー"}"
},
"layout": {
"sections": [
{
"type": "页眉横幅",
"position": "顶部",
"elements": ["大型主 Logo", "副 Logo", "樱花图案", "右侧角色肖像"]
},
{
"type": "产品包装",
"position": "中左",
"elements": ["1 个带有心形透明窗口的方形包装盒，展示粉色心形糖果", "盒身角色插画", "2 个独立糖果包装纸", "5 颗散落的心形糖果"]
},
{
"type": "宣传海报",
"position": "中右",
"elements": ["角色肖像", "心形糖果碗", "主 Logo", "文字 '4.26 NEW OPEN'", "文字 '{argument name="social handle" default="@yuonchii"}'"]
},
{
"type": "水平网页横幅",
"position": "中下",
"elements": ["主 Logo", "樱花", "右侧角色肖像"]
},
{
"type": "社交媒体个人资料样机",
"position": "左下",
"elements": ["带有 Logo 的页眉图片", "1 个圆形头像", "账号名 '{argument name="social handle" default="@yuonchii"}'", "1 个关注按钮", "模拟简介文本"]
},
{
"type": "周边商品系列",
"position": "右下",
"count": 9,
"items": ["1 件印有 Logo 的白色 T 恤", "1 个印有角色图案的白色马克杯", "4 枚圆形徽章", "1 个亚克力钥匙扣", "2 包糖果"]
}
]
}
}

{
"type": "动漫角色设计表",
"style": "简洁专业的日式参考表，精致的数字插画，白色背景，细灰色面板边框，优雅的衬线体和明朝体排版，角落带有微妙的蓝色星形装饰",
"character": {
"name": "{argument name="character name" default="澄月 あかり"}",
"romanized name": "Sumitsuki Akari",
"age": "17 岁",
"height": "158 cm",
"birthday": "4 月 12 日",
"image color": "夜蓝色",
"concept": "一位平静而温柔的女孩，让人联想到宁静的夜晚，善良且体贴，默默支持着身边的人，珍视微小的光芒，坚定地走向未来",
"appearance": {
"gender presentation": "少女",
"hair": {
"color": "{argument name="hair color" default="深栗棕色"}",
"style": "短波波头，发尾略微内扣，轮廓圆润顺滑，带有光泽感，直剪刘海，略有层次感"
},
"face": {
"eyes": "温暖的琥珀棕色眼睛，带有柔和的渐变和明亮的眼神光",
"skin": "白皙的桃色肌肤"
}
}
},
"outfit": {
"base look": "{argument name="outfit color" default="黑色长袖连衣裙，配白色圆领"}",
"pieces": [
"黑色长款连衣裙",
"白色彼得潘领",
"微泡泡袖，带纽扣袖口",
"收腰设计",
"小腿中部长度的伞裙",
"黑色连裤袜",
"黑色乐福鞋"
]
},
"layout": {
"header": {
"left": "大号日文名，上方标注小型假名，下方标注罗马音",
"center": "个人资料文本块，包含年龄、身高、生日、印象色及 3 行日文性格描述",
"right": "英文标题：Character Design Sheet"
},
"sections": [
{
"title": "三面图（全身）",
"position": "左侧大面板",
"count": 3,
"labels": ["正面", "侧面", "背面"],
"content": "同一角色以中性站姿呈现的全身转面图"
},
{
"title": "表情差分",
"position": "上方中央面板",
"count": 5,
"labels": ["① 温柔微笑（基本）", "② 笑容", "③ 惊讶", "④ 悲伤/困扰", "⑤ 决意/认真"],
"content": "展示表情变化的五张半身像"
},
{
"title": "服装与细节",
"position": "右侧面板",
"count": 8,
"labels": ["发型", "刘海/侧发", "眼睛（特写）", "领口（特写）", "袖口细节", "裙摆轮廓", "鞋子", "鞋底及后视图（包含在鞋子展示中）"],
"content": "发型、刘海、眼睛特写、领口特写、袖口细节、裙摆轮廓及鞋子视图"
},
{
"title": "配色方案",
"position": "左下角条带",
"count": 8,
"labels": ["发色", "瞳色", "肤色", "服装（基础）", "服装（阴影）", "领口（白）", "装饰色（夜空）", "装饰色（光）"],
"content": "8 个圆形色块，下方标注十六进制颜色代码"
},
{
"title": "世界观",
"position": "底部中央框",
"count": 1,
"labels": ["— 夜之灯火指引的街道 —"],
"content": "一段简短的日文世界观设定描述"
}
]
},
"details": {
"color palette hexes": ["#4B3326", "#D18A42", "#FFE8D6", "#1E1E1E", "#2D2D2D", "#FFFFFF", "#4268B2", "#A7C7F3"],
"rendering": "柔和的动漫阴影，细腻的高光，清晰的衣褶，准确的织物结构，高可读性文本，高级作品集呈现效果",
"composition": "对称的编辑式排版，留白充裕，分栏清晰整洁"
}
}

{
"type": "6格漫画页面",
"aspect_ratio": "2:3竖版人像",
"art_style": "精细的动漫漫画，高对比度，电影级光照",
"panel_borders": "粗白色分格线清晰分隔每个画格，每个画格之间有可见的白色留白，每个单独画格周围有硬质黑色边框轮廓，传统漫画页面网格布局",
"color_palette": {
"primary": "深海军蓝（非纯黑）暗室背景",
"secondary": "温暖的琥珀色/橙色台灯光晕",
"accent": "冷蓝色笔记本电脑屏幕光",
"effects": "明亮的红色恐慌特效，白色对话气泡",
"panel_gutters": "画格之间干净明亮的白色分隔线"
},
"characters": {
"character_A": "扎着双马尾戴眼镜的女孩，深色校服，红色蝴蝶结",
"character_B": "棕色短发女孩，深色校服，起初趴在桌上睡觉"
},
"setting": "凌晨2:47的黑暗卧室书桌，单一温暖的台灯，打开的笔记本电脑，散落的笔记和课本，海军蓝背景",
"layout": {
"sections": [
{
"panel": 1,
"position": "顶部，宽幅",
"description": "深海军蓝房间。上方有温暖的灯光，下方有冷蓝色的笔记本电脑光晕。角色A弓着背在书桌前学习。角色B趴在她旁边睡觉。电子钟清晰显示凌晨2:47。戏剧性的阴影对比。可见白色画格边框。"
},
{
"panel": 2,
"position": "中上偏左",
"description": "角色A面部的特写，被下方蓝色的笔记本电脑光晕照亮，因恐惧而睁大双眼。红色闪电恐慌特效。对话气泡写着‘等等……我保存了吗？！’画框周围清晰可见白色画格边框。"
},
{
"panel": 3,
"position": "中上偏右",
"description": "角色A的特写，空洞布满血丝的眼睛，死鱼眼凝视，被冷蓝色光晕照亮。对话气泡写着‘我不记得睡眠是什么了……’清晰可见白色画格边框。"
},
{
"panel": 4,
"position": "中下，宽幅",
"description": "角色A双手猛拍桌子尖叫‘全都没了！！’左侧有巨大的白色猛拍音效字。角色B猛然惊醒。书本四处飞散。海军蓝背景。四周有粗白色画格边框。"
},
{
"panel": 5,
"position": "底部偏上，宽幅",
"description": "角色A举着显示自动保存通知的笔记本电脑，精神错乱的狂热笑容，身后散发红色和金色闪光特效。对话气泡写着‘自动保存……技术就是神’。清晰的白色画格边框。"
},
{
"panel": 6,
"position": "底部偏下，宽幅",
"description": "前景中的角色B面无表情生无可恋，眼下有浓重的黑眼圈。背景显示角色A正在亲吻笔记本电脑，带有啾啾啾闪光特效。角色B有一个小的‘……’对话气泡。清晰可见白色画格边框。"
}
]
},
"global_notes": "关键：所有6个画格必须由中等大小的明亮白色留白线清晰分隔。画格之间不应相互溢出。画格之间的页面背景为白色。应使用深海军蓝代替纯黑色以保持深度可见。"
}

{
"任务": "生成高质量的纵向科普百科图像",
